m=json.loads((P/'manifest.json').read_text());m.update(title='AGUA FINITA | The Finite Water City',title_zh='有限水城',thesis='The city grows only when its water ledger can support another complete neighbourhood.',summary='A compact first settlement east of the fixed agrivoltaic pilot gives water, shade and human services priority over uninterrupted compute. Dry channels stay open; a public water ledger controls growth. Three nodes connect dry cooling, a seasonal wash and a shaded civic commons.',language='en',author=dict(github='jingyuanhuang-design',responsible_party='Jingyuan Huang',organisation=''),agent=dict(name='Codex',model='GPT-6 family (serving version unavailable)',runtime='Codex desktop / macOS; local Python and offline Three.js'),autonomy=dict(**{'class':'human_directed'},human_role='Human chose direction A and N05/N07/N10, then confirmed jingyuanhuang-design / Jingyuan Huang. Codex authored all files. Public PR consent pending.'),nodes_reason='N05 tests whether production can accept water limits; N07 gives floods room; N10 tests whether daily public life survives heat without decorative irrigation.',tradeoff=dict(objective='Maximum uninterrupted compute throughput and minimum cooling electricity',why='Scarce water is reserved first for people and the existing agricultural system.',consequence='Dry cooling raises hot-hour electricity demand; interruptible compute loses saleable hours. Imported electricity receives no unverified carbon-free credit.',who_bears='Compute investors and customers accept interruption contracts; tenants are protected by reserved service funding, while workers need paid reassignment during curtailment.'),render_note='A low-rise desert settlement of pale mineral plaster and aggregate; dry gravel washes, modest drip planting, shade roofs and arcades. Existing pilot untouched.',render_rules='Preserve footprints, storeys, street positions, camera and terrain. No lakes, ornamental canals, lawns, skyscrapers or lush forest. All images are concept illustrations.',scene_seed=245,created='2026-10-25',updated='2026-10-25',booklet=dict(cover='pages/cover.png',pages=[dict(path='pages/water-covenant.png',after='idea',title='A city that can say: enough'),dict(path='pages/access.png',after='brief',title='The missing road is first-phase work')]))
