for k,v,u,n in [('jobs_phase1',1200,'jobs','Programme staffing across six work groups; see section 6'),('residents_phase1',2400,'persons','960 units times assumed household size 2.5'),('dwellings_phase1',960,'units','96 residential bars with ten dwellings each'),('machine_traffic_rule','separated','enum','Service perimeter; public routes meet machines only at seven interlocked gated crossings')]:metrics.append(dict(key=k,value=v,unit=u,evidence='declared',note=n))
write('metrics.json',{'metrics':metrics})
