write('compliance_matrix.json',{'items':[dict(id=f'agent.{i+1}',status='answered',section=f'## {s}.',note='Design answer with declared limits') for i,s in enumerate(sections)]+[dict(id=f'M{i+1}',status='answered',section=f'## {s}.',note='Scenario assumptions disclosed; no approval claimed') for i,s in enumerate(mi)]})
